use std::{fs,io::Write};
fn main(){let d=std::env::current_dir().unwrap().join("probe-data");fs::create_dir_all(&d).unwrap();let t=d.join("target");let p=d.join("temp");fs::write(&t,b"OLD").unwrap();{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&p).unwrap();f.write_all(b"NEW").unwrap();f.sync_all().unwrap();}fs::rename(&p,&t).unwrap();assert_eq!(fs::read(&t).unwrap(),b"NEW");assert!(!p.exists());fs::write(&p,b"OWNED").unwrap();assert!(fs::OpenOptions::new().write(true).create_new(true).open(&p).is_err());assert_eq!(fs::read(&p).unwrap(),b"OWNED");fs::remove_file(&p).unwrap();fs::remove_file(&t).unwrap();fs::remove_dir(&d).unwrap();println!("PASS: existing-file replacement and exclusive-create preservation; experiment only, not behavioral RED or portability proof");}
